#pragmanewdecls required

#include<sourcemod>

#include<sdkhooks>

#include<sdktools>

#include<dhooks>

#undef REQUIRE\_PLUGIN

#include<l4d2\_hittable\_control>

#define Z\_TANK 8

#define TEAM\_INFECTED 3

#define TEAM\_SPECTATOR 1

#define MAX\_EDICTS 2048//(1 << 11)

ConVar

g\_hTankPropFade=null,

g\_hCvartankPropsGlow=null,

g\_hCvarRange=null,

g\_hCvarRangeMin=null,

g\_hCvarColor=null,

g\_hCvarTankOnly=null,

g\_hCvarTankSpec=null,

g\_hCvarTankPropsBeGone=null;

ArrayList

g\_hTankProps=null,

g\_hTankPropsHit=null;

int

g\_iEntityList\[MAX\_EDICTS\] = {-1, ...},

g\_iTankClient=-1,

g\_iCvarRange=0,

g\_iCvarRangeMin=0,

g\_iCvarColor=0;

bool

g\_bCvarTankOnly=false,

g\_bCvarTankSpec=false,

g\_bTankSpawned=false,

g\_bHittableControlExists=false;

publicPluginmyinfo=

{

name="L4D2 Tank Hittable Glow",

author="Harry Potter, Sir, A1m\`, Derpduck",

version="2.5.1",

description="Stop tank props from fading whilst the tank is alive + add Hittable Glow."

};

publicvoidOnPluginStart()

{

g\_hCvartankPropsGlow=CreateConVar("l4d\_tank\_props\_glow", "1", "Show Hittable Glow for infected team while the tank is alive", FCVAR\_NOTIFY);

g\_hCvarColor=CreateConVar("l4d2\_tank\_prop\_glow\_color", "255 255 255", "Prop Glow Color, three values between 0-255 separated by spaces. RGB Color255 - Red Green Blue.", FCVAR\_NOTIFY);

g\_hCvarRange=CreateConVar("l4d2\_tank\_prop\_glow\_range", "4500", "How near to props do players need to be to enable their glow.", FCVAR\_NOTIFY);

g\_hCvarRangeMin=CreateConVar("l4d2\_tank\_prop\_glow\_range\_min", "256", "How near to props do players need to be to disable their glow.", FCVAR\_NOTIFY);

g\_hCvarTankOnly=CreateConVar("l4d2\_tank\_prop\_glow\_only", "0", "Only Tank can see the glow", FCVAR\_NOTIFY);

g\_hCvarTankSpec=CreateConVar("l4d2\_tank\_prop\_glow\_spectators", "1", "Spectators can see the glow too", FCVAR\_NOTIFY);

g\_hCvarTankPropsBeGone=CreateConVar("l4d2\_tank\_prop\_dissapear\_time", "10.0", "Time it takes for hittables that were punched by Tank to dissapear after the Tank dies.", FCVAR\_NOTIFY);

GetCvars();

g\_hTankPropFade=FindConVar("sv\_tankpropfade");

g\_hCvartankPropsGlow.AddChangeHook(TankPropsGlowAllow);

g\_hCvarColor.AddChangeHook(ConVarChanged\_Glow);

g\_hCvarRange.AddChangeHook(ConVarChanged\_Range);

g\_hCvarRangeMin.AddChangeHook(ConVarChanged\_RangeMin);

g\_hCvarTankOnly.AddChangeHook(ConVarChanged\_Cvars);

g\_hCvarTankSpec.AddChangeHook(ConVarChanged\_Cvars);

PluginEnable();

}

publicvoidOnAllPluginsLoaded()

{

g\_bHittableControlExists=LibraryExists("l4d2\_hittable\_control");

}

publicvoidOnLibraryRemoved(constchar\[\] name)

{

if (StrEqual(name, "l4d2\_hittable\_control", true)) {

g\_bHittableControlExists=false;

}

}

publicvoidOnLibraryAdded(constchar\[\] name)

{

if (StrEqual(name, "l4d2\_hittable\_control", true)) {

g\_bHittableControlExists=true;

}

}

voidConVarChanged\_Cvars(ConVarhConvar, constchar\[\] sOldValue, constchar\[\] sNewValue)

{

GetCvars();

}

voidGetCvars()

{

g\_bCvarTankOnly=g\_hCvarTankOnly.BoolValue;

g\_bCvarTankSpec=g\_hCvarTankSpec.BoolValue;

g\_iCvarRange=g\_hCvarRange.IntValue;

g\_iCvarRangeMin=g\_hCvarRangeMin.IntValue;

charsColor\[16\];

g\_hCvarColor.GetString(sColor, sizeof(sColor));

g\_iCvarColor=GetColor(sColor);

}

voidTankPropsGlowAllow(HandlehConVar, constchar\[\] sOldValue, constchar\[\] sNewValue)

{

if (!g\_hCvartankPropsGlow.BoolValue) {

PluginDisable();

} else {

PluginEnable();

}

}

voidConVarChanged\_Glow(HandlehConVar, constchar\[\] sOldValue, constchar\[\] sNewValue)

{

GetCvars();

if (!g\_bTankSpawned) {

return;

}

intiRef=INVALID\_ENT\_REFERENCE, iValue=0, iSize=g\_hTankPropsHit.Length;

for (inti=0; i<iSize; i++) {

iValue=g\_hTankPropsHit.Get(i);

if (iValue>0&&IsValidEdict(iValue)) {

iRef=g\_iEntityList\[iValue\];

if (IsValidEntRef(iRef)) {

SetEntProp(iRef, Prop\_Send, "m\_iGlowType", 3);

SetEntProp(iRef, Prop\_Send, "m\_glowColorOverride", g\_iCvarColor);

}

}

}

}

voidConVarChanged\_Range(ConVarhConVar, constchar\[\] sOldValue, constchar\[\] sNewValue)

{

GetCvars();

if (!g\_bTankSpawned) {

return;

}

if (g\_hTankProps.FindValue(iEntity) ==-1) {

charsModelName\[PLATFORM\_MAX\_PATH\];

GetEntPropString(iEntity, Prop\_Data, "m\_ModelName", sModelName, sizeof(sModelName));

if (StrContains(sModelName, "atlas\_break\_ball") !=-1\|\|StrContains(sModelName, "forklift\_brokenlift.mdl") !=-1) {

g\_hTankProps.Push(iEntity);

g\_hTankPropsHit.Push(iEntity);

CreateTankPropGlow(iEntity);

} elseif (StrContains(sModelName, "forklift\_brokenfork.mdl") !=-1) {

RemoveEntity(iEntity);

}

}

}

boolIsValidEntRef(intiRef)

{

return (iRef>0&&EntRefToEntIndex(iRef) !=INVALID\_ENT\_REFERENCE);

}

intGetColor(char\[\] sTemp)

{

if (strcmp(sTemp, "") ==0) {

return0;

}

charsColors\[3\]\[4\];

intiColor=ExplodeString(sTemp, "", sColors, 3, 4);

if (iColor!=3) {

return0;

}

iColor=StringToInt(sColors\[0\]);

iColor+=256\*StringToInt(sColors\[1\]);

iColor+=65536\*StringToInt(sColors\[2\]);

returniColor;

}

intGetTankClient()

{

if (g\_iTankClient==-1\|\|!IsValidAliveTank(g\_iTankClient)) {

g\_iTankClient=FindTank();

}

returng\_iTankClient;

}

intFindTank()

{

for (inti=1; i<=MaxClients; i++) {

if (IsAliveTank(i)) {

returni;

}

}

return-1;

}

boolIsValidAliveTank(intiClient)

{

return (iClient>0&&iClient<=MaxClients&&IsAliveTank(iClient));

}

boolIsAliveTank(intiClient)

{

return (IsClientInGame(iClient) &&GetClientTeam(iClient) ==TEAM\_INFECTED&&IsTank(iClient));

}

boolIsTank(intiClient)

{

return (GetEntProp(iClient, Prop\_Send, "m\_zombieClass") ==Z\_TANK&&IsPlayerAlive(iClient));

}

